/* Wrapper */
.custom-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  border: 1px solid #e5e7eb;
}

/* Table */
.comparison-table {
  width: 100%;
/*   min-width: 950px; */
  border-collapse: collapse;
  background: #fff;
  position: relative;
	margin-bottom:0;
}
.comparison-table tbody tr:last-child td {
    border: none !important;
}
/* Cells */
.comparison-table th,
.comparison-table td {
  padding: 18px 20px;
  text-align: left;
  border-bottom: 1px solid #e5e7eb;
  vertical-align: top;
  line-height: 1.6;
  font-size: 15px;
}
.comparison-table tbody tr:nth-child(even) {
    background: #e5e5e5;
}

.comparison-table tbody tr:hover {
    background: #f7f7f7;
}

/* Header */
.comparison-table thead th {
  background: #111827;
  color: #fff;
  font-weight: 400;
	letter-spacing:1px;
  position: sticky;
  top: 0;
  z-index: 5;
}

/* First Column Freeze */
.comparison-table th:first-child,
.comparison-table td:first-child {
  position: sticky;
  left: 0;
  z-index: 4;
  min-width: 180px;
  font-weight: 700;
  box-shadow: 4px 0 10px rgba(0,0,0,0.05);
}

/* Header + First Column Fix */
.comparison-table thead th:first-child {
  background: #111827;
  z-index: 6;
}


/* Tablet */
@media (max-width: 991px) {
  .comparison-table th,
  .comparison-table td {
    padding: 16px;
    font-size: 14px;
  }

  .comparison-table {
    min-width: 850px;
  }
}

/* Mobile */
@media (max-width: 767px) {
  .custom-table-wrapper {
    border-radius: 12px;
  }

  .comparison-table {
    min-width: 780px;
  }

  .comparison-table th,
  .comparison-table td {
    padding: 14px;
    font-size: 13px;
    line-height: 1.5;
  }

  .comparison-table th:first-child,
  .comparison-table td:first-child {
    min-width: 140px;
  }
}

