/* WHY POINTS */



    :root {
      --gsapbg: #050608;
      --gsappanel: #0b0d12;
      --gsappanel-2: #11141c;
      --gsapborder: rgba(255, 255, 255, 0.095);
      --gsaptext: #f7f9ff;
      --gsapmuted: #aeb6ca;
      --gsapsoft: #70788c;
      --gsapbrand: #ff6500;
      --gsapbrand-soft: rgba(255, 101, 0, 0.16);
      --gsapradius-xl: 28px;
      --gsapradius-lg: 22px;
      --gsapmax: 1180px;
      color-scheme: dark;
    }

    .ppf-section {
      position: relative;
      overflow: clip;
      padding: clamp(72px, 8vw, 124px) 20px;
    }

    .ppf-section::before {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background-image:
        linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
      background-size: 54px 54px;
      mask-image: radial-gradient(circle at 50% 18%, black, transparent 68%);
    }

    .ppf-container {
      position: relative;
      z-index: 1;
      max-width: var(--gsapmax);
      margin: 0 auto;
    }

    .ppf-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 16px;
      padding: 8px 12px;
      border: 1px solid var(--gsapborder);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.045);
      color: var(--gsapmuted);
